    <!-- Task name & meta -->
    <div class="flex-1 min-w-0">
      <button
        @click="$emit('select')"
        class="block w-full text-left text-sm font-medium text-base-content hover:text-primary truncate"
      >
        {{ task.name }}
      </button>
      <div class="flex items-center gap-3 mt-1 text-xs text-base-content/50">
        <span class="truncate">{{ task.boardTitle }}</span>
        <template v-if="task.due_date">
          <span class="flex items-center gap-1" :class="dueDateClass">
            <i class="fa-regular fa-clock"></i>
            {{ formatDueDate(task.due_date) }}
          </span>
        </template>
      </div>
    </div>

    <!-- Quick actions -->
    <div class="flex items-center gap-1 shrink-0">
      <button
        @click="openPriorityMenu"
        class="btn btn-ghost btn-xs rounded-md text-base-content/50 hover:text-base-content"
        aria-label="Change priority"
      >
        <i class="fa-solid fa-flag"></i>
      </button>
      <button
        @click="openDueDatePicker"
        class="btn btn-ghost btn-xs rounded-md text-base-content/50 hover:text-base-content"
        aria-label="Set due date"
      >
        <i class="fa-regular fa-calendar"></i>
      </button>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    task: { type: Object, required: true },
    index: { type: Number, default: 0 }
  },
  emits: ['select', 'update-priority', 'update-due-date'],
  computed: {
    priorityClass() {
      const p = this.task.priority || 'low'
      return {
        high: 'bg-error/10 text-error',
        medium: 'bg-warning/10 text-warning',
        low: 'bg-success/10 text-success'
      }[p] || 'bg-base-300 text-base-content/60'
    },
    dueDateClass() {
      const due = new Date(this.task.due_date)
      const today = new Date()
      if (due < today) return 'text-error'
      if (due.toDateString() === today.toDateString()) return 'text-warning'
      return 'text-base-content/60'
    }
  },
  methods: {
    formatDueDate(dateStr) {
      const d = new Date(dateStr)
      return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' })
    },
    openPriorityMenu() {
      // Implement a small dropdown to select priority
      // Example: this.$refs.priorityMenu.open()
    },
    openDueDatePicker() {
      // Implement date picker
    }
  }
}
</script>
```

### 5. Follow‑up View – Dashboard

**File:** `src/components/followup/FollowupView.vue`

```vue
<script setup>
import MetricsGrid from './MetricsGrid.vue'
import OverdueTasksList from './OverdueTasksList.vue'
import ActivityFeed from './ActivityFeed.vue'
import BoardProgressSummary from './BoardProgressSummary.vue'
</script>

<template>
  <div class="followup-view overflow-auto p-4 lg:p-6">
    <!-- Header with filters -->
    <div class="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
      <h1 class="text-lg font-semibold text-base-content">Follow‑up</h1>
      <div class="flex items-center gap-2">
        <div class="join">
          <button
            v-for="range in ranges"
            :key="range.value"
            @click="selectedRange = range.value"
            class="btn btn-sm join-item"
            :class="selectedRange === range.value ? 'btn-primary' : 'btn-ghost'"
          >
            {{ range.label }}
          </button>
        </div>
        <select
          v-model="assigneeFilter"
          class="select select-bordered select-sm bg-base-100"
          aria-label="Filter by assignee"
        >
          <option value="all">All assignees</option>
          <option v-for="user in allUsers" :key="user" :value="user">{{ user }}</option>
        </select>
      </div>
    </div>

    <!-- Metrics grid -->
    <MetricsGrid :metrics="metrics" />

    <!-- Lower section: overdue + activity -->
    <div class="grid grid-cols-1 lg:grid-cols-3 gap-6 mt-6">
      <OverdueTasksList
        :tasks="overdueTasks"
        class="lg:col-span-2"
      />
      <ActivityFeed :events="recentActivity" />
    </div>

    <!-- Board progress summary -->
    <BoardProgressSummary :boards="boardsProgress" class="mt-6" />
  </div>
</template>

<script>
export default {
  props: {
    project: { type: Object, default: null }
  },
  data() {
    return {
      selectedRange: 'week',
      assigneeFilter: 'all',
      ranges: [
        { label: 'Today', value: 'day' },
        { label: 'Week', value: 'week' },
        { label: 'Month', value: 'month' }
      ]
    }
  },
  computed: {
    allUsers() {
      // Gather unique usernames across all chats
      const users = new Set()
      this.$storex.kanban.allBoards.forEach(board => {
        board.chats.forEach(chat => {
          chat.users?.forEach(u => users.add(u))
        })
      })
      return [...users]
    },
    metrics() {
      // Calculate based on selectedRange and assigneeFilter
      // Returns array: { label, value, icon, trend }
      const now = new Date()
      const tasks = this.$storex.kanban.allBoards.flatMap(b => b.chats)
        .filter(chat => this.inSelectedRange(chat) && this.matchesAssignee(chat))

      const total = tasks.length
      const completed = tasks.filter(t => t.column === 'Done' || t.status === 'completed').length
      const overdue = tasks.filter(t => t.due_date && new Date(t.due_date) < now && !t.completed).length
      const dueToday = tasks.filter(t => t.due_date && new Date(t.due_date).toDateString() === now.toDateString()).length

      return [
        { label: 'Total tasks', value: total, icon: 'fa-solid fa-list-ul', trend: '+2 vs last week' },
        { label: 'Completed', value: completed, icon: 'fa-solid fa-check-circle', trend: `${Math.round(completed/total*100)}% completion` },
        { label: 'Overdue', value: overdue, icon: 'fa-solid fa-exclamation-triangle', trend: overdue > 0 ? 'Needs attention' : 'No overdue' },
        { label: 'Due today', value: dueToday, icon: 'fa-regular fa-clock', trend: dueToday > 0 ? 'Focus today' : 'Clear' }
      ]
    },
    overdueTasks() {
      // Similar filter, return list of overdue tasks with project/board info
      const now = new Date()
      return this.$storex.kanban.allBoards.flatMap(board =>
        board.chats
          .filter(chat => chat.due_date && new Date(chat.due_date) < now && !chat.completed)
          .map(chat => ({ ...chat, boardTitle: board.title }))
      )
    },
    recentActivity() {
      // Combine messages, tool events, etc. Filter by date range
      // Simplified: return mock data or derived from store
      return [
        { type: 'message', user: 'alice', text: 'Added comment to "Login bug"', time: '2h ago' },
        { type: 'status', user: 'bob', text: 'Moved "API docs" to Done', time: '3h ago' },
        { type: 'priority', user: 'carol', text: 'Changed priority of "DB migration" to high', time: '5h ago' }
      ]
    },
    boardsProgress() {
      // For each board, compute completion percentage
      return this.$storex.kanban.allBoards.map(board => {
        const total = board.chats.length
        const done = board.chats.filter(c => c.column === 'Done').length
        return {
          title: board.title,
          total,
          completed: done,
          percentage: total ? Math.round(done / total * 100) : 0
        }
      })
    }
  },
  methods: {
    inSelectedRange(chat) {
      if (!chat.created_at) return true
      const created = new Date(chat.created_at)
      const now = new Date()
      switch (this.selectedRange) {
        case 'day': return created.toDateString() === now.toDateString()
        case 'week': return created >= new Date(now.setDate(now.getDate() - 7))
        case 'month': return created >= new Date(now.setMonth(now.getMonth() - 1))
        default: return true
      }
    },
    matchesAssignee(chat) {
      return this.assigneeFilter === 'all' || chat.users?.includes(this.assigneeFilter)
    }
  }
}
</script>
```

