import { createStore, Store } from 'vuex'
import {
  useAccessor,
} from 'typed-vuex'
import { API } from '../api/api'

import * as session from './session'
import * as projects from './project'
import * as ui from './ui'
import * as users from './users'
import * as profiles from './profiles'
import * as logs from './logs'
import * as chats from './chats'
import * as teams from './teams'
import * as media from './media'
import * as views from './views'
import * as toast from './toast'
import * as kanban from './kanban'
import * as planning from './planning'
import * as browsers from './browsers'
import * as meets from './meets'

const modules = { 
  session,
  projects,
  ui,
  users,
  profiles,
  logs,
  chats,
  teams,
  media,
  views,
  toast,
  kanban,
  planning,
  browsers,
  meets 
}
const storePattern = {
  state () {
    return {
    }
  },
  modules,
}


let store = null
let storex = null
store = createStore(storePattern)
storex = useAccessor(store, storePattern)
storex.init = async () => {
  await Promise.all(Object.keys(modules).map(async m => {
    if (storex[m].init) {
      await storex[m].init(storex)
    }
  }))
}
storex.store = store
storex.api = API

export default storex.store
export const $storex = storex

