import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'

export const namespaced = true

// ─── Config ──────────────────────────────────────────────────────────────────

export const PRIORITIES = {
  high: {
    value: 'high',
    label: 'High',
    icon: 'fa-solid fa-flag',
    badge: 'border-error/30 bg-error/10 text-error',
    dot: 'bg-error'
  },
  medium: {
    value: 'medium',
    label: 'Medium',
    icon: 'fa-solid fa-flag',
    badge: 'border-warning/30 bg-warning/10 text-warning',
    dot: 'bg-warning'
  },
  low: {
    value: 'low',
    label: 'Low',
    icon: 'fa-solid fa-flag',
    badge: 'border-success/30 bg-success/10 text-success',
    dot: 'bg-success'
  }
}

export const TASK_STATUS = {
  todo:   { value: 'todo',   label: 'To Do',       icon: 'fa-regular fa-circle',       color: 'text-base-content/40' },
  doing:  { value: 'doing',  label: 'In Progress', icon: 'fa-solid fa-circle-play',    color: 'text-primary' },
  onhold: { value: 'onhold', label: 'On Hold',     icon: 'fa-solid fa-circle-pause',   color: 'text-warning' },
  done:   { value: 'done',   label: 'Done',        icon: 'fa-solid fa-circle-check',   color: 'text-success' }
}

const PRIORITY_WEIGHT = { high: 0, medium: 1, low: 2 }

// ─── Date helpers (relative to "today" so overdue/upcoming stay realistic) ───

function daysFromNow(days) {
  const d = new Date()
  d.setDate(d.getDate() + days)
  return d.toISOString().slice(0, 10) // YYYY-MM-DD
}

function today() {
  return new Date().toISOString().slice(0, 10)
}

function hoursAgo(hours) {
  return new Date(Date.now() - hours * 3600 * 1000).toISOString()
}

// ─── Mock data ────────────────────────────────────────────────────────────────

function createMockTasks() {
  return [
    { id: 't1',  name: 'Fix login redirect loop',          board: 'Backend',  column: 'In Progress', priority: 'high',   dueDate: daysFromNow(-2), assignees: ['alice', 'robert'], status: 'doing',  progress: 60, subtasks: 2, updatedAt: hoursAgo(2) },
    { id: 't2',  name: 'DB migration for user roles',      board: 'Backend',  column: 'To Do',       priority: 'high',   dueDate: daysFromNow(-1), assignees: [],                  status: 'todo',   progress: 0,  subtasks: 0, updatedAt: hoursAgo(26) },
    { id: 't3',  name: 'Migrate auth to OAuth2',           board: 'Backend',  column: 'To Do',       priority: 'high',   dueDate: daysFromNow(4),  assignees: ['alice'],          status: 'todo',   progress: 0,  subtasks: 0, updatedAt: hoursAgo(30) },
    { id: 't4',  name: 'Design planning view mockups',     board: 'Product',  column: 'In Progress', priority: 'medium', dueDate: daysFromNow(0),  assignees: ['carol'],          status: 'doing',  progress: 45, subtasks: 3, updatedAt: hoursAgo(5) },
    { id: 't5',  name: 'Update API docs',                  board: 'Docs',     column: 'To Do',       priority: 'medium', dueDate: daysFromNow(9),  assignees: [],                  status: 'todo',   progress: 0,  subtasks: 0, updatedAt: hoursAgo(8) },
    { id: 't6',  name: 'Add dark mode toggle',             board: 'Frontend', column: 'To Do',       priority: 'low',    dueDate: null,              assignees: ['robert'],         status: 'todo',   progress: 0,  subtasks: 0, updatedAt: hoursAgo(12) },
    { id: 't7',  name: 'Refactor kanban store',            board: 'Frontend', column: 'Done',        priority: 'medium', dueDate: daysFromNow(-3), assignees: ['bob'],            status: 'done',   progress: 100, subtasks: 0, updatedAt: hoursAgo(4) },
    { id: 't8',  name: 'Fix mobile sidebar overflow',      board: 'Frontend', column: 'Done',        priority: 'high',   dueDate: daysFromNow(-5), assignees: ['robert', 'carol'], status: 'done',   progress: 100, subtasks: 1, updatedAt: hoursAgo(50) },
    { id: 't9',  name: 'Set up CI pipeline',               board: 'DevOps',   column: 'On Hold',     priority: 'medium', dueDate: daysFromNow(7),  assignees: ['alice'],          status: 'onhold', progress: 20, subtasks: 0, updatedAt: hoursAgo(60) },
    { id: 't10', name: 'Write unit tests for chat store',  board: 'Backend',  column: 'To Do',       priority: 'medium', dueDate: daysFromNow(5),  assignees: [],                  status: 'todo',   progress: 0,  subtasks: 0, updatedAt: hoursAgo(20) },
    { id: 't11', name: 'Improve search relevance',         board: 'Docs',     column: 'To Do',       priority: 'low',    dueDate: null,              assignees: ['carol'],          status: 'todo',   progress: 0,  subtasks: 0, updatedAt: hoursAgo(22) },
    { id: 't12', name: 'Update onboarding docs',           board: 'Docs',     column: 'Done',        priority: 'low',    dueDate: daysFromNow(-1), assignees: ['bob'],            status: 'done',   progress: 100, subtasks: 0, updatedAt: hoursAgo(70) }
  ]
}

function createMockActivity() {
  return [
    { id: 'a1', actor: 'alice',       type: 'status',   text: 'moved "Fix login redirect loop" to In Progress',       target: 't1',  timeLabel: '2h ago',  time: hoursAgo(2),   tone: 'info' },
    { id: 'a2', actor: 'bob',         type: 'status',   text: 'completed "Refactor kanban store"',                     target: 't7',  timeLabel: '4h ago',  time: hoursAgo(4),   tone: 'success' },
    { id: 'a3', actor: 'codx-junior', type: 'created',  text: 'created "DB migration for user roles"',                 target: 't2',  timeLabel: '1d ago',  time: hoursAgo(26),  tone: 'primary' },
    { id: 'a4', actor: 'carol',       type: 'priority', text: 'set priority of "Design planning view mockups" to High', target: 't4',  timeLabel: '1d ago',  time: hoursAgo(28),  tone: 'warning' },
    { id: 'a5', actor: 'robert',      type: 'assigned', text: 'was assigned to "Fix mobile sidebar overflow"',          target: 't8',  timeLabel: '2d ago',  time: hoursAgo(50),  tone: 'info' },
    { id: 'a6', actor: 'alice',       type: 'due',      text: 'set a due date on "Migrate auth to OAuth2"',             target: 't3',  timeLabel: '2d ago',  time: hoursAgo(54),  tone: 'warning' }
  ]
}

// ─── State ────────────────────────────────────────────────────────────────────

export const state = () => ({
  tasks: createMockTasks(),
  activity: createMockActivity(),
  selectedTaskId: null,
  filter: '',
  boardFilter: 'all',
  assigneeFilter: 'all',
  rangeFilter: 'all'
})

// ─── Module-level helpers ─────────────────────────────────────────────────────

function byPriorityAndDue(a, b) {
  const pa = PRIORITY_WEIGHT[a.priority] ?? 2
  const pb = PRIORITY_WEIGHT[b.priority] ?? 2
  if (pa !== pb) return pa - pb

  const aDue = a.dueDate || '9999-12-31'
  const bDue = b.dueDate || '9999-12-31'
  if (aDue !== bDue) return aDue < bDue ? -1 : 1
  return (a.name || '').localeCompare(b.name || '')
}

function inRange(task, range) {
  if (!task.dueDate) return false
  const diff = Math.round((new Date(task.dueDate) - new Date(today())) / 86400000)

  switch (range) {
    case 'today': return diff === 0
    case 'week': return diff >= 0 && diff <= 7
    case 'month': return diff >= 0 && diff <= 30
    default: return true
  }
}

// ─── Getters ──────────────────────────────────────────────────────────────────

export const getters = getterTree(state, {
  allTasks: state => state.tasks,

  selectedTask: state => state.tasks.find(t => t.id === state.selectedTaskId) || null,

  boards: state => [...new Set(state.tasks.map(t => t.board))].sort(),

  assignees: state => [...new Set(state.tasks.flatMap(t => t.assignees || []))].sort(),

  priorityConfig: () => priority => PRIORITIES[priority] || PRIORITIES.low,

  statusConfig: () => status => TASK_STATUS[status] || TASK_STATUS.todo,

  filteredTasks: (state) => {
    return state.tasks.filter(task => {
      if (state.boardFilter !== 'all' && task.board !== state.boardFilter) return false
      if (state.assigneeFilter !== 'all' && !(task.assignees || []).includes(state.assigneeFilter)) return false
      if (state.rangeFilter !== 'all' && !inRange(task, state.rangeFilter)) return false
      if (state.filter) {
        const q = state.filter.toLowerCase()
        const hay = `${task.name || ''} ${task.board || ''} ${task.column || ''}`.toLowerCase()
        if (!hay.includes(q)) return false
      }
      return true
    })
  },

  priorityGroups: (state, getters) => {
    const groups = { high: [], medium: [], low: [] }
    getters.filteredTasks.forEach(task => {
      (groups[task.priority] || groups.low).push(task)
    })

    for (const key of Object.keys(groups)) {
      groups[key].sort((a, b) => {
        const ao = a.sort_order ?? Number.MAX_SAFE_INTEGER
        const bo = b.sort_order ?? Number.MAX_SAFE_INTEGER
        if (ao !== bo) return ao - bo
        return byPriorityAndDue(a, b)
      })
    }
    return groups
  },

  metrics: (state, getters) => {
    const tasks = getters.filteredTasks
    const now = today()
    const total = tasks.length
    const done = tasks.filter(t => t.status === 'done').length
    const active = tasks.filter(t => t.status === 'doing' || t.status === 'todo').length
    const onHold = tasks.filter(t => t.status === 'onhold').length
    const overdue = tasks.filter(t => t.dueDate && t.dueDate < now && t.status !== 'done').length
    const dueToday = tasks.filter(t => t.dueDate === now && t.status !== 'done').length
    const completion = total ? Math.round((done / total) * 100) : 0

    return { total, done, active, onHold, overdue, dueToday, completion }
  },

  needsAttention: (state, getters) => {
    const now = today()
    return getters.filteredTasks
      .filter(t => t.status !== 'done')
      .filter(t => {
        const overdue = t.dueDate && t.dueDate < now
        const dueToday = t.dueDate === now
        const unassignedHigh = t.priority === 'high' && !(t.assignees || []).length
        return overdue || dueToday || unassignedHigh
      })
      .sort(byPriorityAndDue)
  },

  boardProgress: (state, getters) => {
    const map = {}
    getters.filteredTasks.forEach(task => {
      if (!map[task.board]) map[task.board] = { board: task.board, total: 0, done: 0 }
      map[task.board].total += 1
      if (task.status === 'done') map[task.board].done += 1
    })

    return Object.values(map)
      .map(b => ({ ...b, percentage: b.total ? Math.round((b.done / b.total) * 100) : 0 }))
      .sort((a, b) => a.board.localeCompare(b.board))
  },

  activityFeed: state => [...state.activity].sort((a, b) => (a.time > b.time ? -1 : 1))
})

// ─── Mutations ────────────────────────────────────────────────────────────────

export const mutations = mutationTree(state, {
  setSelectedTaskId(state, taskId) {
    state.selectedTaskId = taskId || null
  },

  setFilter(state, filter) {
    state.filter = filter || ''
  },

  setBoardFilter(state, board) {
    state.boardFilter = board || 'all'
  },

  setAssigneeFilter(state, assignee) {
    state.assigneeFilter = assignee || 'all'
  },

  setRangeFilter(state, range) {
    state.rangeFilter = range || 'all'
  },

  updateTask(state, { taskId, updates }) {
    state.tasks = state.tasks.map(t => t.id === taskId ? { ...t, ...updates } : t)
  },

  reorderTasks(state, orderedIds) {
    const order = new Map(orderedIds.map((id, index) => [id, index]))
    state.tasks = state.tasks.map(t => ({
      ...t,
      sort_order: order.has(t.id) ? order.get(t.id) : (t.sort_order ?? Number.MAX_SAFE_INTEGER)
    }))
  }
})

// ─── Actions ──────────────────────────────────────────────────────────────────

export const actions = actionTree(
  { state, getters, mutations },
  {
    async init() {
      // Mock data is seeded by the state factory. No remote fetch needed.
    },

    selectTask({ state }, taskId) {
      mutations.setSelectedTaskId(state, taskId)
    },

    clearSelection({ state }) {
      mutations.setSelectedTaskId(state, null)
    },

    setFilter({ state }, filter) {
      mutations.setFilter(state, filter)
    },

    setBoardFilter({ state }, board) {
      mutations.setBoardFilter(state, board)
    },

    setAssigneeFilter({ state }, assignee) {
      mutations.setAssigneeFilter(state, assignee)
    },

    setRangeFilter({ state }, range) {
      mutations.setRangeFilter(state, range)
    },

    updatePriority({ state }, { taskId, priority }) {
      mutations.updateTask(state, { taskId, updates: { priority } })
    },

    updateDueDate({ state }, { taskId, dueDate }) {
      mutations.updateTask(state, { taskId, updates: { dueDate: dueDate || null } })
    },

    updateStatus({ state }, { taskId, status }) {
      mutations.updateTask(state, { taskId, updates: { status } })
    },

    updateProgress({ state }, { taskId, progress }) {
      mutations.updateTask(state, { taskId, updates: { progress: Math.max(0, Math.min(100, Number(progress) || 0)) } })
    },

    toggleAssignee({ state, getters }, { taskId, username }) {
      const task = getters.allTasks.find(t => t.id === taskId)
      if (!task) return
      const assignees = task.assignees || []
      const next = assignees.includes(username)
        ? assignees.filter(u => u !== username)
        : [...assignees, username]
      mutations.updateTask(state, { taskId, updates: { assignees: next } })
    },

    reorderTasks({ state }, orderedIds) {
      mutations.reorderTasks(state, orderedIds)
    }
  }
)

