                ? 'btn-primary'
                : 'btn-ghost border border-base-100 text-base-content/50'"
            >
              <i :class="selectedTask.assignees?.includes(user) ? 'fa-solid fa-circle-check' : 'fa-regular fa-circle'" class="text-[10px]"></i>
              {{ user }}
            </button>
