  nextPage() {
    this.page += 1
    return this
  }

  /**
   * Move to previous page
   */
  previousPage() {
    if (this.page > 1) {
      this.page -= 1
    }
    return this
  }

  /**
   * Reset to first page
   */
  resetPage() {
