      this.page -= 1
    }
    return this
  }

  /**
   * Reset to first page
   */
  resetPage() {
    this.page = 1
    return this
  }

  /**
   * Serialize to JSON for API request
   */
  toJSON() {
    return {
      query: this.query,
      from_date: this.from_date || undefined,
      to_date: this.to_date || undefined,
      page: this.page,
      page_size: this.page_size,
      filters: this.allFiltersEnabled() ? undefined : this.filters
    }
  }

  /**
   * Create from JSON response
   */
  static fromJSON(json) {
    return new ChatSearchRequest(json)
  }

  /**
   * Clone this request
   */
  clone() {
    return new ChatSearchRequest(this.toJSON())
  }
}

export default ChatSearchRequest

async searchChats({ state }, options = {}) {
  let searchRequest

  if (options instanceof ChatSearchRequest) {
    searchRequest = options
  } else {
    const hasDateRange = !!(options.from_date || options.to_date)
    if ((!options.query || options.query.trim() === '') && !hasDateRange) {
